    BibEntry entry1 = new BibEntry().withField(StandardField.TITLE, "Quantum Physics");
    BibEntry entry2 = new BibEntry().withField(StandardField.TITLE, "Organic Chemistry");

    bibDatabaseContext.getDatabase().insertEntry(entry1);
    bibDatabaseContext.getDatabase().insertEntry(entry2);

    // Trigger consecutive searches via the searchQueryProperty
    searchQueryProperty.setValue(Optional.of(new SearchQuery("Quantum")));
    searchQueryProperty.setValue(Optional.of(new SearchQuery("Organic")));

    // Wait for BackgroundTask to complete
    Thread.sleep(500);

    long matchingCount = mainTableDataModel.getEntriesFilteredAndSorted().stream()
            .filter(view -> view.isMatchedBySearch().get())
            .count();

    assertEquals(1, matchingCount, "Previous search results are still visible!");
}

